tring)($_POST['full_name']??''));$email=trim((string)($_POST['email']??''));$role=(string)($_POST['role']??'Viewer');$status=(string)($_POST['status']??'Active');$divisionId=(int)($_POST['division_id']??0);$areaId=(int)($_POST['area_id']??0);$newPassword=(string)($_POST['new_password']??'');if($username===''||$fullName===''){flash('error','User ID and Name / Full Name are required.');}elseif(!in_array($role,['Administrator','Editor','Viewer','Guest'],true)||!in_array($status,['Active','Inactive'],true)){flash('error','Invalid role or status.');}elseif($newPassword!==''&&strlen($newPassword)<8){flash('error','New password must be at least 8 characters.');}else{try{$check=$pdo->prepare("SELECT id FROM users WHERE (username=? OR (?<>'' AND agency_id=?)) AND id<>? LIMIT 1");$check->execute([$username,$agencyId,$agencyId,$id]);if($check->fetch()){flash('error','That User ID or Agency ID is already assigned to another account.');}else{if($areaId>0){$areaCheck=$pdo->prepare('SELECT id FROM areas WHERE id=? AND division_id=? LIMIT 1');$areaCheck->execute([$areaId,$divisionId]);if(!$areaCheck->fetchColumn()){$areaId=0;}}if($newPassword!==''){$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,full_name=?,email=?,role=?,status=?,division_id=?,area_id=?,password_hash=?,must_change_password=0 WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$fullName,$email,$role,$status,$divisionId>0?$divisionId:null,$areaId>0?$areaId:null,password_hash($newPassword,PASSWORD_DEFAULT),$id]);}else{$st=$pdo->prepare('UPDATE users SET username=?,agency_id=?,full_name=?,email=?,role=?,status=?,division_id=?,area_id=? WHERE id=?');$st->execute([$username,$agencyId===''?null:$agencyId,$fullName,$email,$role,$status,$divisionId>0?$divisionId:null,$areaId>0?$areaId:null,$id]);}flash('success','User account updated.');}}catch(Throwable $e){flash('error','Unable to update user account. Please check the User ID and Agency ID.');}}header('Location:users.php');exit;}elseif($action==