$head->execute([$divisionId,$personName]);$isDivisionHead=(bool)$head->fetchColumn();
$canonicalName=$personRow['name']??($isDivisionHead?$personName:'');
$areaId=(int)($personRow['area_id']??0);
if($divisionId<=0 || $canonicalName===''){flash('error','Please select a valid Division/Department and Name / Full Name assigned to that Division.');}
else{
$st=$pdo->prepare('INSERT INTO users(username,agency_id,full_name,email,password_hash,role,status,must_change_password,division_id,area_id) VALUES(?,?,?,?,?,?,?,?,?,?)');$st->execute([trim($_POST['username']),(($a=trim($_POST['agency_id']??''))===''?null:$a),$canonicalName,trim($_POST['email']),password_hash($p,PASSWORD_DEFAULT),$_POST['role'],$_POST['status'],1,$divisionId,$areaId]);flash('success','User created.');}}}elseif($action==='toggle'){$pdo->prepare('UPDATE users SET status=IF(status="Active","Inactive","Active") WHERE id=?')->execute([(int)$_POST['id']]);flash('success','User status updated.');}header('Location:users.php');exit;}$editId=(int)($_GET['edit']??0);$editUser=null;if($editId>0&&$editId!==$myId){$st=$pdo->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$st->execute([$editId]);$editUser=$st->fetch()?:null;}$rows=$pdo->query('SELECT u.id,u.username,u.agency_id,u.full_name,u.email,u.role,u.status,u.created_at,u.division_id,u.area_id,d.name division_name,a.name area_name FROM users u LEFT JOIN divisions d ON d.id=u.division_id LEFT JOIN areas a ON a.id=u.area_id ORDER BY u.full_name')->fetchAll();pageStart('User Management');
?><div class="grid user-management-grid"><div class="panel user-list-panel"><div class="user-list-heading"><h2>Users</h2><div class="user-list-tools"><div class="user-search" id="userSearchBox"><input class="input" type="text" id="userSearchInput" autocomplete="off" placeholder="Search User..." aria-label="Search User"><div class="user-search-suggestions" id="userSearchSuggestions" role="listbox"></div></div><button class="btn user-add-account-btn" type="button" onclick="document.getElementById('create-user-panel').hidden=false;document.getElementById('create-user-panel').scrollIntoView({behavior:'smooth',block:'start'})">Add User Account</button></div></div><div class="user-table-wrap"><div class="user-pagination" id="userPagination" aria-label="User pagination"><div class="user-page-size"><label for="userPageSize">Show</label><select class="input" id="userPageSize" aria-label="Records per page"><option value="10">10</option><option value="20">20</option><option value="50">50</option><option value="100">100</option></select><span>records</span></div><div class="user-pagination-info" id="userPaginationInfo"></div><div class="user-pagination-buttons" id="userPaginationButtons"></div></div><table class="table user-management-table" id="userManagementTable"><thead><tr><th>Name</th><th>User ID / Agency ID</th><th>Division / Area</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr data-user-id="<?=e((string)$r['id'])?>" data-user-name="<?=e($r['full_name'])?>"><td><?=e($r['full_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['username'])?><br><small><?=e($r['agency_id']??'')?></small></td><td><?=e($r['division_name']??'Not assigned')?> / <?=e($r['area_name']??'Not assigned')?></td><td><?=e($r['role'])?></td><td><div class="user-status-actions"><form method="post" class="user-status-toggle-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="user-status-toggle <?=($r['status']==='Active'?'is-active':'is-inactive')?>" type="submit"<?=($r['id']===currentUser()['id']?' disabled title="You cannot deactivate your own account"':'')?>><span class="user-status-toggle-label"><?=e($r['status']==='Active'?'Active':'Inactive')?></span><span class="user-status-toggle-knob"></span></button></form><?php if((int)$r["id"]!==$myId):?><div class="user-row-actions"><a class="btn secondary master-action" href="users.php?edit=<?=(int)$r["id"]?>">Edit</a><form method="post" class="master-action-form" onsubmit="return confirm('Delete this user account? This cannot be undone.')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="id" value="<?=(int)$r["id"]?>"><button class="btn danger master-action" type="submit">Delete</button></form></div><?php else:?><div class="user-row-actions"><a class="btn secondary master-action" href="#edit-my-account" onclick="document.getElementById('edit-my-account').hidden=false">Edit</a></div><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No user accounts found.</td></tr><?php endif;?></tbody></table></div></div><?php if($editUser):?><div class="panel"><h2>Edit User Account</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update_user"><input type="hidden" name="id" value="<?=(int)$editUser["id"]?>"><div class="field"><label>Name / Full Name</label><input class="input" name="full_name" value="<?=e((string)$editUser["full_name"])?>" required></div><div class="field"><label>User ID</label><input class="input" name="username" value="<?=e((string)$editUser["username"])?>" required></div><div class="field"><label>Agency ID (optional)</label><input class="input" name="agency_id" value="<?=e((string)($editUser["agency_id"]??""))?>"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e((string)($editUser["email"]??""))?>"></div><div class="field"><label>Division / Department</label><select class="select" name="division_id" id="editUserDivision"><option value="0">Not assigned</option><?php foreach($divisions as $d):?><option value="<?=$d["id"]?>" <?=((int)$editUser["division_id"]===(int)$d["id"]?"selected":"")?>><?=e($d["name"])?></option><?php endforeach;?></select></div><div class="field"><label>Area / Unit</label><select class="select" name="area_id" id="editUserArea"><option value="0">Not assigned</option><?php foreach($areas as $a):?><option value="<?=$a["id"]?>" data-division="<?=$a["division_id"]?>" <?=((int)$editUser["area_id"]===(int)$a["id"]?"selected":"")?>><?=e($a["name"])?></option><?php endforeach;?></select></div><div class="field"><label>Role</label><select class="select" name="role"><?php foreach(["Administrator","Editor","Viewer","Guest"] as $roleOption):?><option value="<?=e($roleOption)?>" <?=($editUser["role"]===$roleOption?"selected":"")?>><?=e($roleOption)?></option><?php endforeach;?></select></div><div class="field"><label>Status</label><select class="select" name="status"><option value="Active" <?=($editUser["status"]==="Active"?"selected":"")?>>Active</option><option value="Inactive" <?=($editUser["status"]==="Inactive"?"selected":"")?>>Inactive</option></select></div><div class="field"><label>New Password (leave blank to keep current password)</label><input class="input" type="password" name="new_password" minlength="8" autocomplete="new-password"></div><div class="actions"><button class="btn">Save Changes</button><a class="btn btn-secondary" href="users.php">Cancel</a></div></form></div><script>(function(){const d=document.getElementById("editUserDivision"),a=document.getElementById("editUserArea");function filterAreas(){Array.from(a.options).forEach((o,i)=>{if(i)o.hidden=!!d.value&&o.dataset.division!==d.value;});if(a.selectedOptions[0]&&a.selectedOptions[0].hidden)a.value="0";}d.addEventListener("change",filterAreas);filterAreas();})();</script><?php endif;?><div class="panel" id="edit-my-account" hidden><h2>Edit My Account</h2><p class="muted">You can edit only your own account details. Your role, status, and Division/Area assignment cannot be changed here.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update_my_account"><div class="field"><label>User ID</label><input class="input" name="username" value="<?=e((string)($me['username']??''))?>" required></div><div class="field"><label>Agency ID (optional)</label><input class="input" name="agency_id" value="<?=e((string)($me['agency_id']??''))?>"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="<?=e((string)($me['email']??''))?>"></div><div class="field"><label>New Password (leave blank to keep current password)</label><input class="input" type="password" name="new_password" minlength="8" autocomplete="new-password"></div><div class="actions"><button class="btn">Save My Account</button></div></form></div><div class="panel" id="create-user-panel" hidden><h2>Create User</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create">
<div class="field"><label>Division/Department</label><select class="select" name="division_id" id="userDivision" required><option value="">Select Division/Department</option><?php foreach($divisions as $d):?><option value="<?=$d['id']?>" data-head="<?=e($d['division_head']??'')?>" data-position="<?=e($d['head_position_designation']??'')?>"><?=e($d['name'])?></option><?php endforeach;?></select></div>
<div class="field"><label>Select Name / Full Name</label><select class="select" name="full_name" id="userName" required disabled><option value="">Select Name / Full Name</option><?php foreach($divisions as $d):?><option value="<?=e($d['division_head'])?>" data-division="<?=$d['id']?>" data-head="1" data-position="<?=e($d['head_position_designation']??'')?>"><?=e($d['division_head'])?> — Division/Department Head<?php if(($d['head_position_designation']??'')!==''):?> — <?=e($d['head_position_designation'])?><?php endif;?></option><?php endforeach;?><?php foreach($personnel as $p):?><option value="<?=e($p['name'])?>" data-division="<?=$p['division_id']?>" data-area="<?=$p['area_id']?>" data-position="<?=e($p['position_designation']??'')?>"><?=e($p['name'])?> — <?=e($p['area_name'])?><?php if(($p['position_designation']??'')!==''):?> — <?=e($p['position_designation'])?><?php endif;?></option><?php endforeach;?></select></div>
<div class="field"><label>User ID</label><input class="input" name="username" required></div><div class="field"><label>Agency ID <small>(optional)</small></label><input class="input" name="agency_id"></div>
