(function(){
 const d=document.getElementById('userDivision'),n=document.getElementById('userName');
 function filterNames(){const id=d.value;Array.from(n.options).forEach((o,i)=>{if(i)o.hidden=!id||o.dataset.division!==id;});if(!n.value||(n.selectedOptions[0]&&n.selectedOptions[0].hidden))n.value='';n.disabled=!id;}
 d.addEventListener('change',filterNames);filterNames();
})();
</script><style>.user-management-grid{display:block;width:100%;max-width:100%;min-width:0}.user-management-grid>.panel{width:100%;max-width:100%;min-width:0;box-sizing:border-box}.user-add-account-btn{background:#198754!important;border-color:#198754!important;color:#fff!important}.user-add-account-btn:hover{background:#157347!important;border-color:#146c43!important}.user-list-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.user-list-heading h2{margin:0}.user-list-panel{width:100%;min-width:0;max-width:100%;box-sizing:border-box;overflow:visible}.user-table-wrap{display:block;width:100%;min-width:0;max-width:100%;box-sizing:border-box;overflow:visible}.user-management-table{table-layout:fixed;width:100%;min-width:0;max-width:100%;box-sizing:border-box;border-collapse:collapse}.user-management-table th,.user-management-table td{min-width:0;box-sizing:border-box;padding:8px 6px;overflow-wrap:anywhere;word-break:break-word}.user-management-table th,.user-management-table td{text-align:center}.user-management-table th:nth-child(1),.user-management-table td:nth-child(1){width:19%}.user-management-table th:nth-child(2),.user-management-table td:nth-child(2){width:17%}.user-management-table th:nth-child(3),.user-management-table td:nth-child(3){width:24%;min-width:0;max-width:none}.user-management-table th:nth-child(4),.user-management-table td:nth-child(4){width:12%}.user-management-table th:nth-child(5),.user-management-table td:nth-child(5){width:28%}.user-status-actions{display:flex;align-items:center;justify-content:center;gap:5px;flex-wrap:nowrap;white-space:normal}.user-status-toggle-form,.user-row-actions,.user-row-actions .master-action-form{display:inline-flex;align-items:center;margin:0;flex:0 0 auto}.user-row-actions{gap:4px;flex-wrap:nowrap}.user-status-actions .master-action{margin:0;width:60px;min-width:60px;max-width:60px;box-sizing:border-box;padding-left:8px;padding-right:8px;text-align:center;justify-content:center}@media(max-width:900px){.user-management-table th,.user-management-table td{padding:6px 4px;font-size:12px}.user-status-actions{gap:4px}.user-row-actions{gap:4px;flex-wrap:nowrap}}</style><script>
document.addEventListener('DOMContentLoaded',function(){
 const input=document.getElementById('userSearchInput'),suggestions=document.getElementById('userSearchSuggestions'),table=document.getElementById('userManagementTable'),pageSizeSelect=document.getElementById('userPageSize'),paginationInfo=document.getElementById('userPaginationInfo'),paginationButtons=document.getElementById('userPaginationButtons');
 if(!input||!suggestions||!table||!pageSizeSelect||!paginationInfo||!paginationButtons)return;
 const tableRows=Array.from(table.querySelectorAll('tr[data-user-id]'));
 let filteredRows=tableRows.slice(),currentPage=1,pageSize=Number(pageSizeSelect.value)||10;
 function textFor(row){return String(row.innerText||row.textContent||'').replace(/\s+/g,' ').trim();}
 function closeSuggestions(){suggestions.innerHTML='';suggestions.style.display='none';}
 function renderPagination(){
  const total=filteredRows.length,totalPages=Math.max(1,Math.ceil(total/pageSize));if(currentPage>totalPages)currentPage=totalPages;
  tableRows.forEach(function(row){row.style.display='none';row.classList.remove('user-search-selected');});
  const start=(currentPage-1)*pageSize;filteredRows.slice(start,start+pageSize).forEach(function(row){row.style.display='';});
  paginationInfo.textContent=total?'Showing '+(start+1)+'-'+Math.min(start+pageSize,total)+' of '+total+' records':'0 records';
  paginationButtons.innerHTML='';
  function addButton(label,page,disabled,active){const b=document.createElement('button');b.type='button';b.className='btn secondary user-page-button'+(active?' active':'');b.textContent=label;b.disabled=!!disabled;b.addEventListener('click',function(){currentPage=page;renderPagination();});paginationButtons.appendChild(b);}
  addButton('Previous',currentPage-1,currentPage===1,false);
  const max=7;let first=Math.max(1,currentPage-3),last=Math.min(totalPages,first+max-1);first=Math.max(1,last-max+1);
  for(let page=first;page<=last;page++)addButton(String(page),page,false,page===currentPage);
  addButton('Next',currentPage+1,currentPage===totalPages,false);
 }
 function applyFilter(term,selectedId,reset){
  const value=String(term||'').trim().toLowerCase();
  filteredRows=tableRows.filter(function(row){if(selectedId)return row.dataset.userId===selectedId;return !value||textFor(row).toLowerCase().includes(value);});
  if(reset)currentPage=1;renderPagination();if(selectedId)filteredRows.forEach(function(row){row.classList.add('user-search-selected');});
 }
 function showSuggestions(){
  const term=String(input.value||'').trim().toLowerCase();suggestions.innerHTML='';
  if(!term){closeSuggestions();applyFilter('',null,true);return;}
  const matches=tableRows.filter(function(row){return textFor(row).toLowerCase().includes(term);}).slice(0,10);
  if(!matches.length){suggestions.innerHTML='<div class="user-search-empty">No matching user found.</div>';suggestions.style.display='block';applyFilter(term,null,true);return;}
  matches.forEach(function(row){const button=document.createElement('button');button.type='button';button.className='user-search-suggestion';button.setAttribute('role','option');button.dataset.id=row.dataset.userId;button.textContent=row.dataset.userName+' — '+(row.cells[1]?.innerText||'').replace(/\s+/g,' ').trim();suggestions.appendChild(button);});
  suggestions.style.display='block';applyFilter(term,null,true);
 }
 input.addEventListener('input',showSuggestions);input.addEventListener('focus',function(){if(input.value.trim())showSuggestions();});
 input.addEventListener('keydown',function(e){if(e.key==='Escape'){input.value='';closeSuggestions();applyFilter('',null,true);}});
 suggestions.addEventListener('click',function(e){const button=e.target.closest('.user-search-suggestion');if(!button)return;input.value=button.textContent;closeSuggestions();applyFilter('',button.dataset.id,true);});
 pageSizeSelect.addEventListener('change',function(){pageSize=Number(pageSizeSelect.value)||10;currentPage=1;renderPagination();});
 document.addEventListener('click',function(e){const box=document.getElementById('userSearchBox');if(box&&!box.contains(e.target))closeSuggestions();});
 renderPagination();
});
</script><style>
.user-list-tools{display:flex;align-items:center;justify-content:flex-end;gap:12px;flex-wrap:wrap}
.user-search{position:relative;width:200px;min-width:200px;margin:0}
.user-search .input{width:200px;box-sizing:border-box}
.user-search-suggestions{position:absolute;left:0;right:0;top:100%;z-index:1000;background:#fff;border:1px solid #cfd6df;border-radius:4px;box-shadow:0 4px 12px rgba(0,0,0,.12);max-height:240px;overflow-y:auto;display:none}
.user-search-suggestion{display:block;width:100%;padding:9px 12px;border:0;background:#fff;text-align:left;cursor:pointer;font-size:12px}
.user-search-suggestion:hover,.user-search-suggestion:focus{background:#eef5ff}
.user-search-empty{padding:9px 12px;color:#6b7280;font-size:12px}
#userManagementTable tr.user-search-selected td{background:#eef5ff}
.user-pagination{display:flex;align-items:center;justify-content:flex-end;gap:12px;width:100%;clear:both;position:static;float:none;margin:0 0 10px;padding:0;box-sizing:border-box}
.user-pagination-info{flex:0 0 auto;text-align:right;font-size:13px;color:#6b7280}
.user-page-size{display:flex;align-items:center;gap:6px;font-size:14px;color:#4b5563}
.user-page-size .input{width:78px;min-width:78px;height:36px}
.user-pagination-buttons{display:flex;align-items:center;gap:5px;flex-wrap:wrap;justify-content:flex-end}
